type ToolKind = "analysis" | "generator" | "workspace" | "validation" | "release";
type Tool = { id: string; name: string; category: string; kind: ToolKind; description: string; sources: ToolSource[]; focus: string[]; metrics: string[]; actions: string[]; outcome: string };
type ProjectStatus = "Active" | "AI working" | "Needs review" | "Draft" | "Validation" | "Completed";
type ProjectFilter = "All" | "Active" | "Review" | "Drafts" | "Validation" | "Completed";
type ProjectRecord = { id: string; title: string; status: ProjectStatus; toolId: string; store: string; source: ToolSource; updated: string; owner: string; summary: string; resultCount: number; draftLabel: string; versionCount: number; validation: string; exportState: string; nextAction: string };
type StoreTab = "Overview" | "Inventory" | "Projects" | "Drafts" | "Reports" | "Release";
type InventoryStatus = "Healthy" | "Low stock" | "Out of stock" | "Draft";
type InventoryItem = { id: string; name: string; sku: string; category: string; status: InventoryStatus; stock: number; reserved: number; price: string; projectId: string; summary: string; updated: string };
type StoreRecord = { id: string; name: string; provider: string; url: string; status: "Connected" | "Needs attention"; updated: string; projectCount: number; inventoryCount: number; releaseStatus: string };
type EditorMode = "Manual" | "AI proposal";
type PreviewDevice = "Desktop" | "Tablet" | "Mobile";
type PreviewSide = "Before" | "After";
type InventoryReviewState = "Findings" | "Validation" | "Export" | "Release";

